using IndaloAventurApi.Application.Abstractions.Inventario;
using IndaloAventurApi.Domain.Inventario;
using MediatR;
namespace IndaloAventurApi.Application.Features.Inventario.InventarioMateriales.CreateInventarioMaterial;
public sealed class CreateInventarioMaterialCommandHandler(IInventarioMaterialRepository m, IInventarioCategoriaRepository c, IInventarioEstadoRepository e) : IRequestHandler<CreateInventarioMaterialCommand,int> { public async Task<int> Handle(CreateInventarioMaterialCommand r, CancellationToken ct) { if(await c.GetByIdAsync(r.CategoriaId,ct) is null) throw new KeyNotFoundException("La categoria de inventario no existe."); if(await e.GetByIdAsync(r.EstadoId,ct) is null) throw new KeyNotFoundException("El estado de inventario no existe."); var x=InventarioMaterial.Crear(r.Descripcion,r.MarcaModelo,r.Cantidad,r.CategoriaId,r.EstadoId,r.FechaAdquisicion,r.AdquiridoDonado,r.Observaciones,r.NumeroSerie,r.Activo); if(x.NumeroSerieNormalizado is not null && await m.ExistsWithNormalizedSerialAsync(x.NumeroSerieNormalizado,null,ct)) throw new InvalidOperationException("Ya existe un material con ese numero de serie."); await m.AddAsync(x,ct); await m.SaveChangesAsync(ct); return x.Id; } }
